mapper.select:
SELECT id FROM iam_principal WHERE deleted = 0 AND id IN #{id} AND principal_type = #{principalType} AND status = #{status}
AND EXISTS ( SELECT 1 FROM iam_account_principal relation INNER JOIN iam_account account ON account.id = relation.account_id AND account.deleted = 0 AND account.status = 'ACTIVE' AND account.realm_key = #{linkedAccountRealm} INNER JOIN iam_subject subject ON subject.id = account.subject_id AND subject.deleted = 0 AND subject.status = 'ACTIVE' WHERE relation.principal_id = iam_principal.id )
ORDER BY id

mapper.update:
UPDATE iam_principal
status = #{status.value}, deleted = CASE WHEN #{deleted.value} THEN 1 ELSE 0 END, updated_at = CURRENT_TIMESTAMP
WHERE deleted = CASE WHEN #{expectedDeleted} THEN 1 ELSE 0 END AND id IN #{id} AND principal_type = #{principalType}

mapper.select:
SELECT relation.principal_id FROM iam_account_principal relation
INNER JOIN iam_principal principal ON principal.id = relation.principal_id AND principal.deleted = 0
WHERE relation.account_id = #{accountId}
AND principal.principal_type = #{principalType}
AND principal.status = #{status}
ORDER BY relation.principal_id

SELECT relation.principal_id, relation.account_id FROM iam_account_principal relation INNER JOIN iam_account account ON account.id = relation.account_id AND account.deleted = 0 WHERE relation.principal_id IN
#{principalId}
ORDER BY principal_id, account_id

SELECT  FROM iam_account_identifier WHERE deleted = 0
AND id = #{id}
AND account_id = #{accountId}
AND FALSE
ORDER BY identifier_type
